type ImplementationType = string | ModuleScript | IServiceFactory
local InstanceManager = require(script.Parent.Parent.InstancePathManager)

local ServiceLifetimeEnum = require(script.Parent.ServiceLifetime)
type ServiceLifetime = ServiceLifetimeEnum.Type

--[=[
    @class ServiceDescriptor

    服务描述
]=]
local ServiceDescriptor = {}
ServiceDescriptor.__index = ServiceDescriptor

local function ThrowIfNull(value, message)
	if value == nil then
		error(message or "Value cannot be null")
	end
end

local function ThrowIfNotString(value)
	if type(value) ~= "string" or value == "" then
		error("Value must be string and not nil")
	end
end

--- 构建服务描述
function ServiceDescriptor.new(serviceType: string, lifetime: ServiceLifetime)
	assert(serviceType, "serviceType is required")
	assert(lifetime, "lifetime is required")
	assert(type(serviceType) == "string" and serviceType ~= "", "serviceType must be string and not nil")
	local self = setmetatable({}, ServiceDescriptor)
	self.ServiceType = serviceType
	self.Lifetime = lifetime
	return self
end

--- 使用 ModuleScript 构建服务描述
function ServiceDescriptor.newWithModuleScript(
	serviceType: string,
	moduleScript: ModuleScript,
	lifetime: ServiceLifetime
)
	assert(moduleScript, "moduleScript is required")
	assert(serviceType, "serviceType is required")
	assert(type(serviceType) == "string" and serviceType ~= "", "serviceType must be string and not nil")
	assert(lifetime, "lifetime is required")
	local implementationType = InstanceManager.GetPathAndCache(moduleScript)
	assert(implementationType, "can't get implementationType by moduleScript:" .. moduleScript.Name)
	local self = ServiceDescriptor.new(serviceType, lifetime)
	self.ImplementationType = implementationType
	return self
end

--- 使用实例构建服务描述，注意本函数沿用了 .net core的命名习惯，实例只一个具体的对象或者函数，并非 roblox Instance
function ServiceDescriptor.newWithInstance(serviceType: string, instance: Instance, lifetime: ServiceLifetime)
	assert(type(serviceType) == "string" and serviceType ~= "", "serviceType must be string and not nil")
	assert(serviceType, "serviceType is required")
	assert(instance, "Instance is required")
	assert(lifetime, "lifetime is required")
	local self = ServiceDescriptor.new(serviceType, lifetime)
	self.ImplementationInstance = instance
	return self
end

--- 使用类型构建服务描述
function ServiceDescriptor.newWithType(serviceType: string, implementationType: string, lifetime: ServiceLifetime)
	assert(type(serviceType) == "string" and serviceType ~= "", "serviceType must be string and not nil")
	assert(serviceType, "serviceType is required")
	assert(implementationType, "implementationType is required")
	assert(lifetime, "lifetime is required")
	local self = ServiceDescriptor.new(serviceType, lifetime)
	self.ImplementationType = implementationType
	return self
end

--- 使用工厂函数构建服务描述
function ServiceDescriptor.newWithFactory(serviceType: string, factory: IServiceFactory, lifetime: ServiceLifetime)
	assert(type(serviceType) == "string" and serviceType ~= "", "serviceType must be string and not nil")
	assert(serviceType, "serviceType is required")
	assert(factory, "factory is required")
	assert(lifetime, "lifetime is required")
	local self = ServiceDescriptor.new(serviceType, lifetime)
	self.ImplementationFactory = factory
	return self
end

function ServiceDescriptor.newWithVarient(serviceType: string, implementation: ImplementationType, lifetime: string)
	assert(type(serviceType) == "string" and serviceType ~= "", "serviceType must be string and not nil")
	ThrowIfNull(serviceType, "必须提供服务名称")
	ThrowIfNull(implementation, "必须提供服务实现")
	ThrowIfNull(lifetime, "必须提供服务生命周期")
	local descriptor
	if type(implementation) == "string" then
		descriptor = ServiceDescriptor.newWithType(serviceType, implementation, lifetime)
	elseif type(implementation) == "function" then
		descriptor = ServiceDescriptor.newWithFactory(serviceType, implementation, lifetime)
	elseif typeof(implementation) == "Instance" and implementation:isA("ModuleScript") then
		descriptor = ServiceDescriptor.newWithModuleScript(serviceType, implementation, lifetime)
	else
		descriptor = ServiceDescriptor.newWithInstance(serviceType, implementation, lifetime)
	end
	return descriptor
end

function ServiceDescriptor:ToString()
	local lifetime = string.format("ServiceType: %s Lifetime: %s ", self.ServiceType, self.Lifetime)

	if self.ImplementationType then
		return lifetime .. string.format("ImplementationType: %s", self.ImplementationType)
	elseif self.ImplementationFactory then
		return lifetime .. "ImplementationFactory: Delegate"
	else
		return lifetime .. string.format("ImplementationInstance: %s", self.ImplementationInstance)
	end
end

function ServiceDescriptor:GetImplementationType()
	if self.ImplementationType then
		return self.ImplementationType
	elseif self.ImplementationInstance then
		return type(self.ImplementationInstance)
	elseif self.ImplementationFactory then
		return "object"
	end
	error("no implementation type")
end

--- 使用构建瞬时服务描述
function ServiceDescriptor.Transient(serviceType: string, implementationType: ImplementationType)
	assert(type(serviceType) == "string" and serviceType ~= "", "serviceType must be string and not nil")
	return ServiceDescriptor.newWithType(serviceType, implementationType, ServiceLifetimeEnum.Transient)
end

--- 使用构建作用域服务描述
function ServiceDescriptor.Scoped(serviceType: string, implementationType: ImplementationType)
	assert(type(serviceType) == "string" and serviceType ~= "", "serviceType must be string and not nil")
	return ServiceDescriptor.newWithType(serviceType, implementationType, ServiceLifetimeEnum.Scoped)
end

--- 使用构建单例服务描述
function ServiceDescriptor.Singleton(serviceType: string, implementationType: ImplementationType)
	assert(type(serviceType) == "string" and serviceType ~= "", "serviceType must be string and not nil")
	return ServiceDescriptor.newWithType(serviceType, implementationType, ServiceLifetimeEnum.Singleton)
end

return ServiceDescriptor
